export const DEFAULT_MODERN_SCROLL_STACK_ITEMS: ModernScrollStackItem[] = [
  {
    id: "ai-automation",
    title: "AI Automation",
    description:
      "Autonomous workflows that eliminate repetitive tasks and scale operations effortlessly",
    bgColor: "#F7C844",
    textColor: "#2B1C06",
    icon: <AiAutomationIcon />,
    rotation: 0,
  },
  {
    id: "product-strategy",
    title: "Product Strategy",
    description:
      "Data-backed roadmaps engineered to turn ambitious ideas into market-leading products",
    bgColor: "#EB5E30",
    textColor: "#FFFDF9",
    icon: <ProductStrategyIcon />,
    rotation: 3.5,
  },
  {
    id: "cloud-architecture",
    title: "Cloud Architecture",
    description:
      "Resilient, low-latency infrastructure built for global scale and zero-downtime deploys",
    bgColor: "#98E3AD",
    textColor: "#1A4325",
    icon: <CloudArchitectureIcon />,
    rotation: -4.5,
  },
  {
    id: "interactive-motion",
    title: "Interactive Motion",
    description:
      "Physics-driven micro-interactions and fluid transitions that make interfaces feel alive.",
    bgColor: "#4086D6",
    textColor: "#FFFFFF",
    icon: <InteractiveMotionIcon />,
    rotation: 3.5,
  },
];

export const DEFAULT_STACKED_SCROLL_STACK_ITEMS: ModernScrollStackItem[] = [
  {
    id: "velocity",
    badge: "01 · VELOCITY",
    stat: "10x",
    title: "Faster Execution",
    description: "Automated workflows from initial brief to production deploy",
    bgColor: "#1E1B4B",
    textColor: "#EEF2FF",
    icon: <AiAutomationIcon />,
    rotation: 0,
  },
  {
    id: "uptime",
    badge: "02 · RELIABILITY",
    stat: "99.9%",
    title: "Uptime SLA",
    description: "Multi-region edge clusters with zero-downtime failover",
    bgColor: "#065F46",
    textColor: "#ECFDF5",
    icon: <CloudArchitectureIcon />,
    rotation: -6.5,
  },
  {
    id: "turnaround",
    badge: "03 · DELIVERY",
    stat: "48h",
    title: "Turnaround Time",
    description: "From brief to first interactive concept and prototype",
    bgColor: "#C2410C",
    textColor: "#FFF7ED",
    icon: <ProductStrategyIcon />,
    rotation: -2.5,
  },
  {
    id: "satisfaction",
    badge: "04 · IMPACT",
    stat: "4.9★",
    title: "Partner Rating",
    description: "Trusted by high-velocity product teams worldwide",
    bgColor: "#581C87",
    textColor: "#FAF5FF",
    icon: <InteractiveMotionIcon />,
    rotation: 6.5,
  },
];

const DEFAULT_ROTATIONS = [0, 3.5, -4.5, 3.5];
const STACKED_ROTATIONS = [0, -6.5, -2.5, 6.5];

export function ModernScrollStack({
  variant = "fan",
  items,
  eyebrow,
  heading,
  subheading,
  showHeader = false,
  cardOffsetX = 78,
  cardGap = 48,
  stickyTop = 72,
  cardWidth,
  cardHeight,
  scrollerRef,
  className,
}: ModernScrollStackProps) {
  const resolvedItems =
    items ??
    (variant === "stacked"
      ? DEFAULT_STACKED_SCROLL_STACK_ITEMS
      : DEFAULT_MODERN_SCROLL_STACK_ITEMS);
  const resolvedCardWidth = cardWidth ?? (variant === "stacked" ? 430 : 316);
  const resolvedCardHeight = cardHeight ?? (variant === "stacked" ? 308 : 376);

  const sectionRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const innerCardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const currentAnglesRef = useRef<number[]>([]);
  const currentXRef = useRef<number[]>([]);
  const [containerWidth, setContainerWidth] = useState<number>(1024);
  const [viewportHeight, setViewportHeight] = useState<number>(640);

  const count = resolvedItems.length;

  // Measure available container width & viewport height so horizontal fan offset,
  // card size, and exact scroll termination adapt smoothly on all screens.
  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;
    const scroller = scrollerRef?.current ?? null;
    const updateSize = () => {
      setContainerWidth(el.clientWidth || 1024);
      const vh = scroller
        ? scroller.clientHeight
        : typeof window !== "undefined"
          ? window.innerHeight
          : 640;
      setViewportHeight(vh || 640);
    };
    updateSize();
    const ro = new ResizeObserver(updateSize);
    ro.observe(el);
    if (scroller) ro.observe(scroller);
    window.addEventListener("resize", updateSize, { passive: true });
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", updateSize);
    };
  }, [scrollerRef]);

  const isMobile = containerWidth < 480;
  const isSmallScreen = containerWidth < 640;

  const effectiveCardWidth =
    variant === "fan"
      ? isMobile
        ? Math.min(resolvedCardWidth, Math.max(176, Math.round(containerWidth * 0.6)))
        : isSmallScreen
          ? Math.min(resolvedCardWidth, Math.max(210, Math.round(containerWidth * 0.58)))
          : Math.min(resolvedCardWidth, Math.max(240, containerWidth - 64))
      : isMobile
        ? Math.min(resolvedCardWidth, Math.max(216, containerWidth - 44))
        : isSmallScreen
          ? Math.min(resolvedCardWidth, Math.max(260, containerWidth - 56))
          : Math.min(resolvedCardWidth, Math.max(240, containerWidth - 64));

  const effectiveCardHeight =
    effectiveCardWidth < resolvedCardWidth
      ? Math.max(
          variant === "stacked" ? 216 : 228,
          Math.round(resolvedCardHeight * (effectiveCardWidth / resolvedCardWidth)),
        )
      : resolvedCardHeight;

  const horizontalMargin = isMobile ? 24 : 32;
  const maxTotalSpread = Math.max(
    0,
    containerWidth - effectiveCardWidth - horizontalMargin,
  );
  const effectiveOffsetX =
    variant === "stacked"
      ? 0
      : count > 1
        ? Math.min(cardOffsetX, Math.floor(maxTotalSpread / (count - 1)))
        : 0;

  const effectiveStickyTop = isMobile
    ? Math.min(stickyTop, 44)
    : isSmallScreen
      ? Math.min(stickyTop, 56)
      : stickyTop;

  const effectiveCardGap = isMobile
    ? Math.min(cardGap, 32)
    : isSmallScreen
      ? Math.min(cardGap, 40)
      : cardGap;

  // Distance Card 0 travels from the bottom of the viewport up to `effectiveStickyTop`
  const card0TravelDistance = Math.min(
    effectiveCardHeight + effectiveCardGap,
    Math.max(
      isMobile ? 160 : 220,
      viewportHeight - effectiveStickyTop - (isMobile ? 110 : 160),
    ),
  );
  const topSpacerHeight = effectiveStickyTop + card0TravelDistance;

  // Exact spacer inside the sticky content box so scrolling ends the exact
  // moment the last card reaches `effectiveStickyTop`, preventing cards from scrolling up.
  const endSpacerHeight = Math.max(
    0,
    viewportHeight - effectiveStickyTop - effectiveCardHeight,
  );

  // Smooth inertial scroll & damped rotation interpolation:
  // 1. Smooths discrete mousewheel steps on `scrollerRef` into a fluid glide.
  // 2. Smoothly interpolates each card's rotation angle via a damped RAF loop
  //    so cards tilt organically as they lock into `stickyTop`.
  useEffect(() => {
    const scroller = scrollerRef?.current ?? null;
    let transformRafId = 0;
    let wheelRafId = 0;
    let isWheelAnimating = false;
    let targetScrollTop = scroller ? scroller.scrollTop : 0;
    let currentScrollTop = targetScrollTop;

    if (currentAnglesRef.current.length !== count) {
      currentAnglesRef.current = new Array(count).fill(0);
    }
    if (currentXRef.current.length !== count) {
      currentXRef.current = new Array(count).fill(0);
    }

    const getCardProgress = (index: number, scrollerTop: number, startDistance: number) => {
      const wrapperEl = cardRefs.current[index];
      if (!wrapperEl) return 0;
      const rect = wrapperEl.getBoundingClientRect();
      const distanceFromSticky = rect.top - scrollerTop - effectiveStickyTop;
      const raw =
        startDistance > 0
          ? 1 - Math.min(1, Math.max(0, distanceFromSticky / startDistance))
          : 1;
      return raw < 0.5
        ? 4 * raw * raw * raw
        : 1 - Math.pow(-2 * raw + 2, 3) / 2;
    };

    const computeAndApplyTransforms = () => {
      const scrollerTop = scroller
        ? scroller.getBoundingClientRect().top
        : 0;
      const startDistance = effectiveCardHeight + effectiveCardGap;
      let needsMoreFrames = false;

      for (let i = 0; i < count; i++) {
        const innerEl = innerCardRefs.current[i];
        if (!innerEl) continue;

        const targetRotation =
          resolvedItems[i]?.rotation ??
          (variant === "stacked"
            ? STACKED_ROTATIONS[i % STACKED_ROTATIONS.length]
            : DEFAULT_ROTATIONS[i % DEFAULT_ROTATIONS.length]) ??
          0;

        const finalXOffset = (i - (count - 1) / 2) * effectiveOffsetX;

        // Every card (including Card 0) starts at the bottom in the center (x = 0, rotate = 0)
        // and glides into its target horizontal slot & tilt as it rises to `stickyTop`.
        const travelDist = i === 0 ? card0TravelDistance : startDistance;
        const eased = getCardProgress(i, scrollerTop, travelDist);

        const desiredX = eased * finalXOffset;
        const desiredAngle = eased * targetRotation;

        const prevX = currentXRef.current[i] ?? 0;
        const nextX = prevX + (desiredX - prevX) * 0.16;
        if (Math.abs(desiredX - nextX) > 0.05) {
          currentXRef.current[i] = nextX;
          needsMoreFrames = true;
        } else {
          currentXRef.current[i] = desiredX;
        }

        const prevAngle = currentAnglesRef.current[i] ?? 0;
        const nextAngle = prevAngle + (desiredAngle - prevAngle) * 0.16;
        if (Math.abs(desiredAngle - nextAngle) > 0.01) {
          currentAnglesRef.current[i] = nextAngle;
          needsMoreFrames = true;
        } else {
          currentAnglesRef.current[i] = desiredAngle;
        }

        innerEl.style.transform = `translate3d(${currentXRef.current[i].toFixed(2)}px, 0px, 0px) rotate(${currentAnglesRef.current[i].toFixed(3)}deg)`;
      }

      if (needsMoreFrames) {
        transformRafId = requestAnimationFrame(computeAndApplyTransforms);
      } else {
        transformRafId = 0;
      }
    };

    const scheduleTransformUpdate = () => {
      if (!transformRafId) {
        transformRafId = requestAnimationFrame(computeAndApplyTransforms);
      }
    };

    const stepWheelScroll = () => {
      if (!scroller) return;
      const diff = targetScrollTop - currentScrollTop;
      if (Math.abs(diff) > 0.4) {
        currentScrollTop += diff * 0.11;
        scroller.scrollTop = currentScrollTop;
        scheduleTransformUpdate();
        wheelRafId = requestAnimationFrame(stepWheelScroll);
      } else {
        currentScrollTop = targetScrollTop;
        scroller.scrollTop = targetScrollTop;
        isWheelAnimating = false;
        wheelRafId = 0;
        scheduleTransformUpdate();
      }
    };

    const onWheel = (e: WheelEvent) => {
      if (!scroller) return;
      const maxScroll = scroller.scrollHeight - scroller.clientHeight;
      if (maxScroll <= 0) return;

      const delta =
        e.deltaMode === 1
          ? e.deltaY * 32
          : e.deltaMode === 2
            ? e.deltaY * scroller.clientHeight
            : e.deltaY;

      const atTop = scroller.scrollTop <= 0 && delta < 0;
      const atBottom = scroller.scrollTop >= maxScroll - 1 && delta > 0;
      if (atTop || atBottom) return;

      e.preventDefault();
      if (!isWheelAnimating) {
        currentScrollTop = scroller.scrollTop;
        targetScrollTop = currentScrollTop;
      }

      targetScrollTop = Math.max(
        0,
        Math.min(maxScroll, targetScrollTop + delta * 0.8),
      );

      if (!isWheelAnimating) {
        isWheelAnimating = true;
        wheelRafId = requestAnimationFrame(stepWheelScroll);
      }
    };

    const onScroll = () => {
      if (scroller && !isWheelAnimating) {
        currentScrollTop = scroller.scrollTop;
        targetScrollTop = currentScrollTop;
      }
      scheduleTransformUpdate();
    };

    computeAndApplyTransforms();

    const target: EventTarget = scroller ?? window;
    target.addEventListener("scroll", onScroll, { passive: true });
    if (scroller) {
      scroller.addEventListener("wheel", onWheel, { passive: false });
    }
    window.addEventListener("resize", onScroll, { passive: true });

    return () => {
      if (transformRafId) cancelAnimationFrame(transformRafId);
      if (wheelRafId) cancelAnimationFrame(wheelRafId);
      target.removeEventListener("scroll", onScroll);
      if (scroller) {
        scroller.removeEventListener("wheel", onWheel);
      }
      window.removeEventListener("resize", onScroll);
    };
  }, [
    card0TravelDistance,
    count,
    effectiveCardGap,
    effectiveCardHeight,
    effectiveOffsetX,
    effectiveStickyTop,
    resolvedItems,
    scrollerRef,
    variant,
  ]);

  return (
    <section
      ref={sectionRef}
      className={cn(
        "relative w-full pt-0 pb-0 px-3 sm:px-8 select-none",
        className,
      )}
    >
      {showHeader && (
        <div className="max-w-2xl mx-auto text-center flex flex-col items-center gap-2 pt-8 sm:pt-12 mb-6 sm:mb-10">
          {eyebrow && (
            <span className="text-[10px] sm:text-[11px] font-bold uppercase tracking-[0.12em] text-[#E85A34]">
              {eyebrow}
            </span>
          )}
          {heading && (
            <h2 className="text-xl sm:text-[28px] font-bold tracking-[-0.02em] text-foreground leading-tight">
              {heading}
            </h2>
          )}
          {subheading && (
            <p className="text-[12.5px] sm:text-sm text-muted-foreground leading-relaxed max-w-xl mt-0.5">
              {subheading}
            </p>
          )}
        </div>
      )}

      {/* Tall sticky stacking track */}
      <div className="relative mx-auto flex flex-col items-center">
        <div
          aria-hidden="true"
          className="w-full shrink-0 pointer-events-none"
          style={{ height: `${topSpacerHeight}px` }}
        />
        {resolvedItems.map((item, index) => {
          const bgColor = item.bgColor ?? "#F7C844";
          const textColor = item.textColor ?? "#2B1C06";

          return (
            <div
              key={item.id}
              ref={(el) => {
                cardRefs.current[index] = el;
              }}
              className="sticky flex justify-center w-full pointer-events-none"
              style={{
                top: `${effectiveStickyTop}px`,
                marginTop: index === 0 ? "0px" : `${effectiveCardGap}px`,
                zIndex: index + 1,
              }}
            >
              <div
                ref={(el) => {
                  innerCardRefs.current[index] = el;
                }}
                className={cn(
                  "pointer-events-auto relative overflow-hidden flex flex-col justify-between will-change-transform origin-center",
                  variant === "stacked"
                    ? "rounded-[16px] sm:rounded-[20px] p-4 sm:p-8 border border-white/15"
                    : "rounded-[14px] sm:rounded-[16px] p-4 sm:p-9",
                )}
                style={{
                  width: `${effectiveCardWidth}px`,
                  height: `${effectiveCardHeight}px`,
                  backgroundColor: bgColor,
                  color: textColor,
                  transform: "translate3d(0px, 0px, 0px) rotate(0deg)",
                }}
              >
                {variant === "stacked" ? (
                  <>
                    {/* Decorative soft corner glow */}
                    <div
                      aria-hidden="true"
                      className="pointer-events-none absolute -top-20 -right-20 w-48 h-48 rounded-full opacity-20 blur-2xl"
                      style={{ backgroundColor: textColor }}
                    />

                    {/* Top bar: pill badge + icon circle */}
                    <div className="relative z-10 flex items-center justify-between gap-2 sm:gap-3">
                      <span
                        className="inline-flex items-center gap-1.5 sm:gap-2 px-2.5 sm:px-3 py-0.5 sm:py-1 rounded-full text-[9px] sm:text-[11px] font-bold uppercase tracking-[0.11em] sm:tracking-[0.14em]"
                        style={{
                          backgroundColor: "rgba(255,255,255,0.12)",
                          border: "1px solid rgba(255,255,255,0.18)",
                        }}
                      >
                        <span
                          className="w-1.5 h-1.5 rounded-full shrink-0"
                          style={{ backgroundColor: textColor }}
                        />
                        {item.badge ?? `0${index + 1} · HIGHLIGHT`}
                      </span>

                      <div
                        className="w-7 h-7 sm:w-9 sm:h-9 rounded-full flex items-center justify-center shrink-0"
                        style={{
                          backgroundColor: "rgba(255,255,255,0.1)",
                          border: "1px solid rgba(255,255,255,0.16)",
                        }}
                      >
                        <div className="scale-[0.42] sm:scale-[0.52] flex items-center justify-center">
                          {item.icon}
                        </div>
                      </div>
                    </div>

                    {/* Center hero stat + title */}
                    <div className="relative z-10 flex flex-col items-center justify-center text-center my-auto py-1 sm:py-2">
                      {item.stat && (
                        <span className="text-[36px] sm:text-[62px] font-extrabold tracking-[-0.04em] leading-none">
                          {item.stat}
                        </span>
                      )}
                      <h3 className="text-[16px] sm:text-[22px] font-semibold tracking-[-0.02em] leading-tight mt-1 sm:mt-2">
                        {item.title}
                      </h3>
                    </div>

                    {/* Bottom footer row */}
                    <div
                      className="relative z-10 flex items-center justify-between gap-3 sm:gap-4 pt-2.5 sm:pt-3.5 text-center"
                      style={{
                        borderTop: "1px solid rgba(255,255,255,0.15)",
                      }}
                    >
                      <p className="text-[11px] sm:text-[13.5px] leading-snug opacity-85 mx-auto font-normal line-clamp-2">
                        {item.description}
                      </p>
                    </div>
                  </>
                ) : (
                  <>
                    {/* Top-left icon or image */}
                    <div className="flex items-start justify-start">
                      {item.image ? (
                        <img
                          src={item.image}
                          alt={item.title}
                          className="w-8 h-8 sm:w-12 sm:h-12 object-contain"
                          loading="lazy"
                        />
                      ) : (
                        <div className="w-8 h-8 sm:w-12 sm:h-12 flex items-center justify-start [&>svg]:w-full [&>svg]:h-full">
                          {item.icon}
                        </div>
                      )}
                    </div>

                    {/* Bottom-left title & description */}
                    <div className="flex flex-col gap-1.5 sm:gap-2.5 text-left">
                      <h3 className="text-[17px] sm:text-[25px] font-bold tracking-[-0.02em] leading-[1.15]">
                        {item.title}
                      </h3>
                      <p className="text-[11.5px] sm:text-[13.5px] leading-[1.38] sm:leading-[1.45] opacity-90 max-w-[235px] font-normal">
                        {item.description}
                      </p>
                    </div>
                  </>
                )}
              </div>
            </div>
          );
        })}
        <div
          aria-hidden="true"
          className="w-full shrink-0 pointer-events-none"
          style={{ height: `${endSpacerHeight}px` }}
        />
      </div>
    </section>
  );
}

export default ModernScrollStack;
